Import ListNotations. Import KXS.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Notation fmem := (word -> option byte).

Definition y4_body_stmt : Prop :=
  forall (Q : machine_state -> Prop) (mm : fmem) (F : bvmap 5 word) (fc : bv 32)
         (gp tp a0 b0 b1 b2 b3 j9 j11 j14 j19 j21 j24 j28 : word)
         (SPB DT4 DST dcap SS IP0 IP1 IP2 IP3 OP0 OP1 OP2 OP3 : Z) (cells : list deltX2) (buf src : list Z)
         (ops ips bts : list word),
    mem_inv usegs mm -> x2_table_ok cells 11 ->
    bytes_at usegs mm DT4 (firstn (Z.to_nat (4 * 2^11)) (x2_bytes' cells)) ->
    u8arr usegs mm DST (map (Z_to_bv 8) buf) -> zlen buf = dcap ->
    bytes_at usegs mm SS (map (Z_to_bv 8) src) ->
    rw_cells usegs mm (SPB + 312) (map C8 ops) -> length ops = 4%nat ->
    rw_cells usegs mm (SPB + 344) (map C8 ips) -> length ips = 4%nat ->
    rw_cells usegs mm (SPB + 376) (map C8 bts) -> length bts = 4%nat ->
    0 <= SPB -> SPB + 512 <= 2^47 -> 0 < DT4 -> DT4 + 8192 <= SPB ->
    8 <= DST -> DST + dcap <= SPB -> 0 < SS -> SS + zlen src <= SPB ->
    (DST + dcap <= DT4 \/ DT4 + 8192 <= DST) -> (DST + dcap <= SS \/ SS + zlen src <= DST) ->
    SS + 7 <= IP0 -> IP0 + 8 <= SS + zlen src -> SS + 7 <= IP1 -> IP1 + 8 <= SS + zlen src ->
    SS + 7 <= IP2 -> IP2 + 8 <= SS + zlen src -> SS + 7 <= IP3 -> IP3 + 8 <= SS + zlen src ->
    DST <= OP0 -> OP0 + 10 <= DST + dcap -> DST <= OP1 -> OP1 + 10 <= DST + dcap ->
    DST <= OP2 -> OP2 + 10 <= DST + dcap -> DST <= OP3 -> OP3 + 10 <= DST + dcap ->
    bv_unsigned b0 mod 512 <> 0 -> bv_unsigned b1 mod 512 <> 0 -> bv_unsigned b2 mod 512 <> 0 -> bv_unsigned b3 mod 512 <> 0 ->
    (forall (mm' : fmem) (b0' b1' b2' b3' j21' j24' j28' : word) (nb0 nb1 nb2 nb3 d0 d1 d2 d3 : Z),
       munch [(DST, DST + dcap); (SPB + 312, SPB + 408)] mm mm' -> wmono usegs mm mm' -> mem_inv usegs mm' ->
       (exists buf', u8arr usegs mm' DST (map (Z_to_bv 8) buf') /\ zlen buf' = dcap) ->
       0 <= nb0 <= 7 -> 0 <= nb1 <= 7 -> 0 <= nb2 <= 7 -> 0 <= nb3 <= 7 ->
       5 <= d0 <= 10 -> 5 <= d1 <= 10 -> 5 <= d2 <= 10 -> 5 <= d3 <= 10 ->
       bv_unsigned b0' mod 512 <> 0 -> bv_unsigned b1' mod 512 <> 0 ->
       bv_unsigned b2' mod 512 <> 0 -> bv_unsigned b3' mod 512 <> 0 ->
       rw_cells usegs mm' (SPB + 312) [C8 (Z_to_bv 64 (OP0 + d0)); C8 (Z_to_bv 64 (OP1 + d1));
                                        C8 (Z_to_bv 64 (OP2 + d2)); C8 (Z_to_bv 64 (OP3 + d3))] ->
       rw_cells usegs mm' (SPB + 344) [C8 (Z_to_bv 64 (IP0 - nb0)); C8 (Z_to_bv 64 (IP1 - nb1));
                                        C8 (Z_to_bv 64 (IP2 - nb2)); C8 (Z_to_bv 64 (IP3 - nb3))] ->
