  destruct bts as [|w0 [|w1 [|w2 [|w3 [|]]]]]; try discriminate LBT.
  cbn [map] in CO, CI, CB.
  assert (WO : wr_at usegs mm (SPB + 312) 32) by exact (proj2 CO).
  assert (WI : wr_at usegs mm (SPB + 344) 32) by exact (proj2 CI).
  assert (WB : wr_at usegs mm (SPB + 376) 32) by exact (proj2 CB).
  pose proof (y4_x2tab_fact mm DT4 cells TOK TB) as TF.
  pose proof (y4_ctz_tab mm MI) as CTZ.
  pose proof (y4k_x2len cells (y4k_cells_len cells TOK)) as LCB.
  remember (firstn (Z.to_nat (4 * 2^11)) (x2_bytes' cells)) as cbs eqn:ECB.
  assert (LSM : Z.of_nat (length (map (Z_to_bv 8) src)) = zlen src) by (rewrite length_map; reflexivity).
  assert (LBM : Z.of_nat (length (map (Z_to_bv 8) buf)) = dcap) by (rewrite length_map; exact LB).
  assert (RF : all_ro usegs Y4_FA2 64 = true) by (vm_compute; reflexivity).
  assert (RM : all_ro usegs Y4_MUL 8 = true) by (vm_compute; reflexivity).
  pose proof (wr_at_apart_ro usegs mm DST _ Y4_FA2 64 MI (proj2 OUT) ltac:(lia) RF) as DF0.
  pose proof (wr_at_apart_ro usegs mm DST _ Y4_MUL 8 MI (proj2 OUT) ltac:(lia) RM) as DM0.
  pose proof (wr_at_apart_ro usegs mm _ _ Y4_FA2 64 MI WO ltac:(lia) RF) as DF1.
  pose proof (wr_at_apart_ro usegs mm _ _ Y4_MUL 8 MI WO ltac:(lia) RM) as DM1.
  pose proof (wr_at_apart_ro usegs mm _ _ Y4_FA2 64 MI WI ltac:(lia) RF) as DF2.
  pose proof (wr_at_apart_ro usegs mm _ _ Y4_MUL 8 MI WI ltac:(lia) RM) as DM2.
  pose proof (wr_at_apart_ro usegs mm _ _ Y4_FA2 64 MI WB ltac:(lia) RF) as DF3.
  pose proof (wr_at_apart_ro usegs mm _ _ Y4_MUL 8 MI WB ltac:(lia) RM) as DM3.
  remember (zlen src) as n eqn:EN.
  assert (EO0 : exists o, OP0 = DST + o) by (exists (OP0 - DST); lia). destruct EO0 as (o0 & ->).
  assert (EO1 : exists o, OP1 = DST + o) by (exists (OP1 - DST); lia). destruct EO1 as (o1 & ->).
  assert (EO2 : exists o, OP2 = DST + o) by (exists (OP2 - DST); lia). destruct EO2 as (o2 & ->).
  assert (EO3 : exists o, OP3 = DST + o) by (exists (OP3 - DST); lia). destruct EO3 as (o3 & ->).
  assert (EI0 : exists i, IP0 = SS + i) by (exists (IP0 - SS); lia). destruct EI0 as (i0 & ->).
  assert (EI1 : exists i, IP1 = SS + i) by (exists (IP1 - SS); lia). destruct EI1 as (i1 & ->).
  assert (EI2 : exists i, IP2 = SS + i) by (exists (IP2 - SS); lia). destruct EI2 as (i2 & ->).
  assert (EI3 : exists i, IP3 = SS + i) by (exists (IP3 - SS); lia). destruct EI3 as (i3 & ->).
  replace (- DT4 - 1) with (-1 * DT4 - 1) by lia.
  rename SS into SB.
  kx_mkR_fold.
  kx_prep [Y4_IE] 700%nat
    [KZRange o0 0 140737488355328; KZRange o1 0 140737488355328; KZRange o2 0 140737488355328; KZRange o3 0 140737488355328;
     KZRange (dcap - o0) 10 140737488355328; KZRange (dcap - o1) 10 140737488355328;
     KZRange (dcap - o2) 10 140737488355328; KZRange (dcap - o3) 10 140737488355328;
     KZRange (DST + o0) 8 140737488355328; KZRange (DST + o1) 8 140737488355328;
     KZRange (DST + o2) 8 140737488355328; KZRange (DST + o3) 8 140737488355328;
     KZRange i0 7 140737488355328; KZRange i1 7 140737488355328; KZRange i2 7 140737488355328; KZRange i3 7 140737488355328;
     KZRange (n - i0) 8 140737488355328; KZRange (n - i1) 8 140737488355328;
     KZRange (n - i2) 8 140737488355328; KZRange (n - i3) 8 140737488355328;
     KZRange (SB + i0) 8 140737488355328; KZRange (SB + i1) 8 140737488355328;
     KZRange (SB + i2) 8 140737488355328; KZRange (SB + i3) 8 140737488355328;
     KZRange dcap 10 140737488355328; KZRange n 15 140737488355328;
     KZRange DST 8 140737488355328; KZRange SB 1 140737488355328;
     KZRange DT4 1 140737488355328; KZRange SPB 8192 140737488355328;
     KZTab DT4 8192 4 [(2, 0, 11); (3, 1, 2)];
     KZTab Y4_FA2 64 1 [(0, 0, 63)]; KZImg Y4_FA2 (Y4_FA2 + 64); KZImg Y4_MUL (Y4_MUL + 8);
     KZWr DST dcap; KZWr (SPB + 312) 32; KZWr (SPB + 344) 32; KZWr (SPB + 376) 32;
     KZDisj DST dcap DT4 8192; KZDisj DST dcap SB n; KZDisj DST dcap (SPB + 312) 96;
     KZDisj (SPB + 312) 96 DT4 8192; KZDisj (SPB + 312) 96 SB n;
     KZDisj DST dcap Y4_FA2 64; KZDisj DST dcap Y4_MUL 8;
     KZDisj (SPB + 312) 32 Y4_FA2 64; KZDisj (SPB + 312) 32 Y4_MUL 8;
     KZDisj (SPB + 344) 32 Y4_FA2 64; KZDisj (SPB + 344) 32 Y4_MUL 8;
     KZDisj (SPB + 376) 32 Y4_FA2 64; KZDisj (SPB + 376) 32 Y4_MUL 8]
    [(DT4, 8192); (SB, n); (Y4_FA2, 64); (Y4_MUL, 8)].
  y4k_god [false; false; false; false; false; false; false; false].
  all: try y4k_side.
  kx_post_regs.
  y4k_ranges.
  pose proof (munch_refl [(DST, DST + dcap); (SPB + 312, SPB + 408)] mm) as MU.
  pose proof (wmono_refl usegs mm) as WM.
  y4k_munch_wins MU [(DST, dcap); (SPB + 312, 32); (SPB + 344, 32); (SPB + 376, 32)].
  lazymatch goal with KXLF : log_flat ?E ?lg, HK : know_ok ?segs ?E ?m ?kn |- _ =>
    apply (kx_wmono_log segs E mm m lg) in WM;
    assert (MI' : mem_inv segs (mem_denot E m lg))
      by (eapply kx_mem_inv_log; [exact MI | exact KXLF | eapply kx_log_wr_ok; [exact HK | exact KXLF | vm_compute; reflexivity]]);
    pose proof (kx_u8arr_ex segs E m lg DST buf OUT KXLF) as OUT'
  end.
  kx_cells_split CO. kx_cells_split CI. kx_cells_split CB.
  y4k_cells.
  y4k_assoc DST. y4k_assoc SB. kx_norm_m1.
  replace (- DT4 + -1) with (- DT4 - 1) by lia.
  eapply y4k_evt_R; [ eapply K | ].
  all: lazymatch goal with |- mkR _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ = _ => reflexivity | |- _ => idtac end.
  all: try (lazymatch goal with |- munch _ _ _ => exact MU | |- wmono _ _ _ => exact WM | |- mem_inv _ _ => exact MI' end).
  all: try (lazymatch goal with |- exists _, _ => y4k_buf OUT' LB end).
  all: try (lazymatch goal with |- 0 <= _ / _ <= 7 => y4k_nb end).
  all: try (lazymatch goal with |- 5 <= _ <= 10 => first [apply y4_d_bound; lia | lia] end).
  all: try (lazymatch goal with |- _ mod 512 <> 0 => y4k_newbits end).
  all: try (lazymatch goal with |- rw_cells _ _ _ _ => y4k_merge end).
Qed.
